def match(orders):
    import heapq

    buy_heap = []   # max-heap by price: store (-price, seq, id)
    sell_heap = []  # min-heap by price: store (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq','active'}
    trades = []
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def pop_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return item
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active']:
                o['active'] = False
                o['qty'] = 0
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            item = pop_valid(opp_heap)
            if item is None:
                break
            opp_price = item[0] if side == 'sell' else -item[0]
            opp_id = item[2]
            opp_o = book[opp_id]

            if typ != 'market':
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break

            trade_qty = min(remaining, opp_o['qty'])

            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            opp_o['qty'] -= trade_qty

            if opp_o['qty'] <= 0:
                opp_o['active'] = False
                heapq.heappop(opp_heap)
            # else it stays at the top of the heap with reduced qty for next iteration

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, seq)
        # ioc/market remainder discarded; fully-filled limit orders don't rest

    return trades

